<?php declare(strict_types=1);namespace App\Controllers\Admin;use App\Core\Request;use App\Core\Response;use App\Models\AuditLog;use App\Models\Page;use App\Services\CmsService;final class PageController extends AdminController{public function index(Request $O):Response{return $this->view('admin/pages/index',['pages'=>Page::all('slug'),'meta'=>['title'=>t('admin.pages')]]);}public function edit(Request $E,?string $a=null):Response{$r=$a?Page::find((int)$a):null;return $this->view('admin/pages/edit',['item'=>$r,'kind'=>'page','blockTypes'=>CmsService::BLOCK_TYPES,'meta'=>['title'=>$r?t('common.edit'):t('common.create')]]);}public function save(Request $A):Response{if($e=$this->validate($A,['slug'=>'required|slug|max:128'],'/admin/pages')){return $e;}$Q=$A->int('id');$s=['slug'=>$A->str('slug'),'title'=>$this->multilang($A->input('title')),'blocks'=>CmsService::normalizeBlocks($A->input('blocks_json')),'meta_title'=>$this->multilang($A->input('meta_title')),'meta_description'=>$this->multilang($A->input('meta_description')),'is_published'=>$A->bool('is_published')?1:0];$i=Page::findBySlug($s['slug'],false);if($i&&(int)$i['id']!==$Q){$this->flash('error',t('admin.slug_taken'));return $this->redirect($Q?'/admin/pages/'.$Q:'/admin/pages/create');}if($Q){Page::update($Q,$s);}else{$Q=Page::create($s);}AuditLog::log('admin.page_save',$s['slug']);$this->flash('success',t('common.saved'));return $this->redirect('/admin/pages/'.$Q);}public function delete(Request $i,string $D):Response{$C=Page::find((int)$D);if($C&&!(int)$C['is_system']){Page::delete((int)$D);AuditLog::log('admin.page_delete',$C['slug']);$this->flash('success',t('common.deleted'));}return $this->redirect('/admin/pages');}}